JavaScript'in `fetch()` fonksiyonu arka planda FastAPI sunucumuza asenkron HTTP isteği atar:

// Kitapları Çeken JS Kodu:
async function kitaplariGetir() {
    const yanit = await fetch('http://127.0.0.1:8000/kitaplar');
    const veriler = await yanit.json();
    console.log('Sunucudan Gelen Kitaplar:', veriler);
}

async function kitapEkle() {
  const veri = {
    baslik: document.getElementById('baslik').value,
    yazar: document.getElementById('yazar').value,
    sayfa_sayisi: parseInt(document.getElementById('sayfa').value)
  };

  await fetch('http://127.0.0.1:8000/kitaplar', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(veri)
  });
  kitaplariListele();  // Listeyi anında yenile!
}

async function kitapSil(id) {
  await fetch(`http://127.0.0.1:8000/kitaplar/${id}`, { method: 'DELETE' });
  kitaplariListele();
}

